ALTER TABLE public.occurrences ADD COLUMN classification_confirmed_at timestamptz, ADD COLUMN classification_confirmed_by uuid REFERENCES public.profiles(id), ADD COLUMN paused_from_status public.occ_status;
CREATE TABLE public.occurrence_sla_cycles (occurrence_id uuid NOT NULL REFERENCES public.occurrences(id), cycle integer NOT NULL CHECK(cycle>0), started_at timestamptz NOT NULL, due_at timestamptz NOT NULL, solution_proposed_at timestamptz, ended_at timestamptz, paused_business_minutes integer NOT NULL DEFAULT 0, severity public.occ_severity NOT NULL, resolution_minutes integer NOT NULL, resolution_breached boolean NOT NULL DEFAULT false, PRIMARY KEY(occurrence_id,cycle));
GRANT SELECT ON public.occurrence_sla_cycles TO authenticated; GRANT ALL ON public.occurrence_sla_cycles TO service_role;
ALTER TABLE public.occurrence_sla_cycles ENABLE ROW LEVEL SECURITY;
CREATE POLICY cycle_read ON public.occurrence_sla_cycles FOR SELECT TO authenticated USING(public.has_occurrence_access(occurrence_id));
INSERT INTO public.occurrence_sla_cycles(occurrence_id,cycle,started_at,due_at,solution_proposed_at,ended_at,paused_business_minutes,severity,resolution_minutes,resolution_breached) SELECT o.id,o.reopen_count+1,o.resolution_started_at,o.resolution_due_at,o.solution_proposed_at,o.closed_at,o.paused_business_minutes,o.severity,t.resolution_minutes,o.resolution_breached FROM public.occurrences o JOIN public.accounts a ON a.id=o.account_id JOIN public.sla_targets t ON t.policy_id=a.sla_policy_id AND t.severity=o.severity;
CREATE FUNCTION public.capture_sla_cycle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target_minutes integer; BEGIN SELECT t.resolution_minutes INTO STRICT target_minutes FROM public.accounts a JOIN public.sla_targets t ON t.policy_id=a.sla_policy_id AND t.severity=NEW.severity WHERE a.id=NEW.account_id; IF TG_OP='UPDATE' AND NEW.reopen_count>OLD.reopen_count THEN UPDATE public.occurrence_sla_cycles SET ended_at=coalesce(ended_at,now()) WHERE occurrence_id=OLD.id AND cycle=OLD.reopen_count+1; END IF; INSERT INTO public.occurrence_sla_cycles(occurrence_id,cycle,started_at,due_at,solution_proposed_at,ended_at,paused_business_minutes,severity,resolution_minutes,resolution_breached) VALUES(NEW.id,NEW.reopen_count+1,NEW.resolution_started_at,NEW.resolution_due_at,NEW.solution_proposed_at,NEW.closed_at,NEW.paused_business_minutes,NEW.severity,target_minutes,NEW.status IN ('registered','in_analysis','in_treatment','reopened','solution_proposed') AND coalesce(NEW.solution_proposed_at,now())>NEW.resolution_due_at) ON CONFLICT(occurrence_id,cycle) DO UPDATE SET due_at=excluded.due_at,solution_proposed_at=excluded.solution_proposed_at,ended_at=excluded.ended_at,paused_business_minutes=excluded.paused_business_minutes,severity=excluded.severity,resolution_minutes=excluded.resolution_minutes,resolution_breached=occurrence_sla_cycles.resolution_breached OR excluded.resolution_breached; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.capture_sla_cycle() FROM PUBLIC;
CREATE TRIGGER capture_sla_cycle AFTER INSERT OR UPDATE ON public.occurrences FOR EACH ROW EXECUTE FUNCTION public.capture_sla_cycle();
CREATE OR REPLACE FUNCTION public.available_transitions(p_occurrence_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; role public.user_role; permitted boolean; result jsonb:='[]'; contained boolean; root_ok boolean; BEGIN IF NOT public.has_occurrence_access(p_occurrence_id) THEN RAISE EXCEPTION 'Sem acesso à ocorrência'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id; role:=public.current_app_role(); permitted:=role IN ('kam','ops_manager') OR (role='analyst' AND o.assignee_id=auth.uid()); IF o.status='registered' AND role IN ('analyst','kam','ops_manager') THEN result:=result||jsonb_build_array(jsonb_build_object('action','assume','label','Assumir ocorrência','allowed',true,'conditions','[]'::jsonb)); END IF; IF o.status='in_analysis' AND permitted THEN IF o.classification_confirmed_at IS NULL THEN result:=result||jsonb_build_array(jsonb_build_object('action','confirm_classification','label','Confirmar severidade e categoria','allowed',true,'conditions','[]'::jsonb)); END IF; result:=result||jsonb_build_array(jsonb_build_object('action','start_treatment','label','Iniciar tratativa','allowed',o.classification_confirmed_at IS NOT NULL AND o.first_response_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.actions WHERE occurrence_id=o.id AND type='containment'),'conditions',jsonb_build_array(jsonb_build_object('label','Severidade e categoria confirmadas','met',o.classification_confirmed_at IS NOT NULL),jsonb_build_object('label','Primeira resposta registrada','met',o.first_response_at IS NOT NULL),jsonb_build_object('label','Ação de contenção cadastrada','met',EXISTS(SELECT 1 FROM public.actions WHERE occurrence_id=o.id AND type='containment'))))); END IF; IF role IN ('kam','ops_manager') AND o.reopen_count=0 AND o.status IN ('registered','in_analysis','in_treatment','awaiting_customer') THEN result:=result||jsonb_build_array(jsonb_build_object('action','change_classification','label','Revisar severidade e categoria','allowed',true,'conditions','[]'::jsonb)); END IF; IF o.status IN ('in_analysis','in_treatment','reopened') AND permitted THEN result:=result||jsonb_build_array(jsonb_build_object('action','ask_customer','label','Pedir informação ao cliente','allowed',true,'conditions','[]'::jsonb)); END IF; IF o.status='awaiting_customer' AND permitted THEN result:=result||jsonb_build_array(jsonb_build_object('action','customer_replied','label','Registrar resposta e retomar SLA','allowed',true,'conditions','[]'::jsonb)); END IF; IF o.status IN ('in_treatment','reopened') AND permitted THEN contained:=NOT EXISTS(SELECT 1 FROM public.actions WHERE occurrence_id=o.id AND gates_solution AND status<>'done'); root_ok:=o.severity NOT IN ('S1','S2') OR o.problem_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.causes WHERE occurrence_id=o.id AND kind='root' AND status='confirmed'); result:=result||jsonb_build_array(jsonb_build_object('action','propose_solution','label','Registrar solução','allowed',contained AND root_ok,'conditions',jsonb_build_array(jsonb_build_object('label','Contenção e correção concluídas','met',contained),jsonb_build_object('label','Causa raiz confirmada ou problema vinculado para S1/S2','met',root_ok)))); END IF; IF o.status='in_analysis' AND role IN ('kam','ops_manager') THEN result:=result||jsonb_build_array(jsonb_build_object('action','mark_unfounded','label','Marcar como improcedente','allowed',EXISTS(SELECT 1 FROM public.attachments WHERE occurrence_id=o.id),'conditions',jsonb_build_array(jsonb_build_object('label','Evidência anexada','met',EXISTS(SELECT 1 FROM public.attachments WHERE occurrence_id=o.id))))); END IF; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.transition_occurrence(p_occurrence_id uuid,p_action text,p_payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; a public.accounts; t public.sla_targets; target public.occ_status; body text; allowed boolean; paused integer; BEGIN IF NOT public.has_occurrence_access(p_occurrence_id) THEN RAISE EXCEPTION 'Sem acesso à ocorrência'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id FOR UPDATE; SELECT coalesce((v->>'allowed')::boolean,false) INTO allowed FROM jsonb_array_elements(public.available_transitions(o.id)) v WHERE v->>'action'=p_action; IF NOT coalesce(allowed,false) THEN RAISE EXCEPTION 'Transição não permitida ou condições pendentes'; END IF; SELECT * INTO STRICT a FROM public.accounts WHERE id=o.account_id; SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=o.severity; body:=trim(coalesce(p_payload->>'body','')); target:=o.status; CASE p_action WHEN 'confirm_classification' THEN UPDATE public.occurrences SET classification_confirmed_at=now(),classification_confirmed_by=auth.uid() WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,metadata) VALUES(o.id,'system','system',auth.uid(),'Severidade e categoria confirmadas.',jsonb_build_object('severity',o.severity,'category_id',o.category_id)); RETURN jsonb_build_object('status',o.status); WHEN 'change_classification' THEN RAISE EXCEPTION 'Use a revisão de classificação'; WHEN 'assume' THEN target:='in_analysis'; UPDATE public.occurrences SET assignee_id=auth.uid() WHERE id=o.id; WHEN 'start_treatment' THEN target:='in_treatment'; WHEN 'ask_customer' THEN IF body='' THEN RAISE EXCEPTION 'Informe a pergunta ao cliente'; END IF; target:='awaiting_customer'; UPDATE public.occurrences SET paused_since=now(),paused_from_status=o.status,first_response_at=coalesce(first_response_at,now()),first_response_breached=first_response_breached OR (first_response_at IS NULL AND now()>first_response_due_at),resolution_breached=resolution_breached OR now()>resolution_due_at,next_update_due_at=public.add_business_minutes(a.calendar_id,now(),t.update_interval_minutes) WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,metadata) VALUES(o.id,'customer_question','customer',auth.uid(),body,jsonb_build_object('previous_status',o.status)); WHEN 'customer_replied' THEN IF body='' THEN RAISE EXCEPTION 'Informe a resposta recebida'; END IF; IF o.paused_since IS NULL THEN RAISE EXCEPTION 'Pausa inconsistente'; END IF; target:=o.paused_from_status; IF target IS NULL THEN SELECT (metadata->>'previous_status')::public.occ_status INTO target FROM public.occurrence_events WHERE occurrence_id=o.id AND kind='customer_question' ORDER BY created_at DESC,id DESC LIMIT 1; END IF; IF target IS NULL OR target NOT IN ('in_analysis','in_treatment','reopened') THEN RAISE EXCEPTION 'Estado anterior da pausa indisponível'; END IF; paused:=public.business_minutes_between(a.calendar_id,o.paused_since,now()); UPDATE public.occurrences SET paused_business_minutes=paused_business_minutes+paused,paused_since=NULL,paused_from_status=NULL,resolution_due_at=public.add_business_minutes(a.calendar_id,o.resolution_started_at,t.resolution_minutes+o.paused_business_minutes+paused),next_update_due_at=CASE WHEN o.next_update_due_at IS NULL THEN NULL ELSE public.add_business_minutes(a.calendar_id,o.next_update_due_at,paused) END WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,metadata) VALUES(o.id,'customer_reply','internal',auth.uid(),body,jsonb_build_object('paused_business_minutes',paused)); WHEN 'propose_solution' THEN IF length(body)<20 THEN RAISE EXCEPTION 'Descreva a solução com pelo menos 20 caracteres'; END IF; target:='solution_proposed'; UPDATE public.occurrences SET solution_text=body,solution_proposed_at=now(),resolution_breached=resolution_breached OR now()>resolution_due_at WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body) VALUES(o.id,'solution','customer',auth.uid(),body); WHEN 'mark_unfounded' THEN IF length(body)<30 THEN RAISE EXCEPTION 'Justifique com pelo menos 30 caracteres'; END IF; target:='closed_unfounded'; UPDATE public.occurrences SET unfounded_justification=body,closed_at=now() WHERE id=o.id; ELSE RAISE EXCEPTION 'Ação inválida'; END CASE; UPDATE public.occurrences SET status=target,updated_at=now() WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,from_status,to_status) VALUES(o.id,'status_change','system',auth.uid(),nullif(body,''),o.status,target); RETURN jsonb_build_object('status',target); END $$;
CREATE FUNCTION public.revise_occurrence_classification(p_occurrence_id uuid,p_impact public.occ_level,p_urgency public.occ_level,p_category_id uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; a public.accounts; t public.sla_targets; BEGIN IF NOT public.has_occurrence_access(p_occurrence_id) OR public.current_app_role() NOT IN ('kam','ops_manager') THEN RAISE EXCEPTION 'Somente KAM ou gestor pode revisar a classificação'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id FOR UPDATE; IF o.reopen_count>0 THEN RAISE EXCEPTION 'Revisão após reabertura aguarda definição da política de recálculo'; END IF; IF o.status NOT IN ('registered','in_analysis','in_treatment','awaiting_customer') OR length(trim(coalesce(p_reason,'')))=0 THEN RAISE EXCEPTION 'Informe a justificativa em uma ocorrência ativa'; END IF; IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=p_category_id AND active AND parent_id IS NULL) THEN RAISE EXCEPTION 'Categoria inválida'; END IF; SELECT * INTO STRICT a FROM public.accounts WHERE id=o.account_id; SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=public.calculate_severity(p_impact,p_urgency); UPDATE public.occurrences SET impact=p_impact,urgency=p_urgency,category_id=p_category_id,subcategory_id=CASE WHEN category_id=p_category_id THEN subcategory_id ELSE NULL END,classification_confirmed_at=now(),classification_confirmed_by=auth.uid(),first_response_due_at=public.add_business_minutes(a.calendar_id,o.created_at,t.first_response_minutes),resolution_due_at=public.add_business_minutes(a.calendar_id,o.created_at,t.resolution_minutes+o.paused_business_minutes),first_response_breached=first_response_breached OR coalesce(o.first_response_at,now())>public.add_business_minutes(a.calendar_id,o.created_at,t.first_response_minutes),resolution_breached=resolution_breached OR (o.status<>'awaiting_customer' AND now()>public.add_business_minutes(a.calendar_id,o.created_at,t.resolution_minutes+o.paused_business_minutes)) WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,metadata) VALUES(o.id,'system','system',auth.uid(),trim(p_reason),jsonb_build_object('action','classification_revision','old_severity',o.severity,'new_severity',t.severity,'old_category_id',o.category_id,'new_category_id',p_category_id)); END $$;
REVOKE ALL ON FUNCTION public.revise_occurrence_classification(uuid,public.occ_level,public.occ_level,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.revise_occurrence_classification(uuid,public.occ_level,public.occ_level,uuid,text) TO authenticated;
CREATE FUNCTION public.reopen_occurrence_from_customer(p_occurrence_id uuid,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; a public.accounts; t public.sla_targets; BEGIN IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Reabertura exclusiva do cliente por avaliação validada'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id FOR UPDATE; IF length(trim(coalesce(p_reason,'')))=0 OR o.status NOT IN ('solution_proposed','closed_resolved','closed_no_evaluation') THEN RAISE EXCEPTION 'Reabertura não permitida'; END IF; IF o.status<>'solution_proposed' AND (o.closed_at IS NULL OR now()>o.closed_at+interval '15 days') THEN RAISE EXCEPTION 'Prazo de reabertura encerrado'; END IF; SELECT * INTO STRICT a FROM public.accounts WHERE id=o.account_id; SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=o.severity; UPDATE public.occurrences SET status='reopened',reopen_count=reopen_count+1,resolution_started_at=now(),resolution_due_at=public.add_business_minutes(a.calendar_id,now(),t.resolution_minutes),paused_business_minutes=0,paused_since=NULL,paused_from_status=NULL,solution_proposed_at=NULL,closed_at=NULL,next_update_due_at=public.add_business_minutes(a.calendar_id,now(),t.update_interval_minutes),updated_at=now() WHERE id=o.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,body,from_status,to_status,metadata) VALUES(o.id,'evaluation','customer',trim(p_reason),o.status,'reopened',jsonb_build_object('cycle',o.reopen_count+2)); RETURN jsonb_build_object('status','reopened','cycle',o.reopen_count+2); END $$;
REVOKE ALL ON FUNCTION public.reopen_occurrence_from_customer(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reopen_occurrence_from_customer(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.sla_tick() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.occurrences SET first_response_breached=true WHERE NOT first_response_breached AND first_response_at IS NULL AND now()>first_response_due_at AND status IN ('registered','in_analysis','in_treatment','awaiting_customer','reopened'); UPDATE public.occurrences SET resolution_breached=true WHERE NOT resolution_breached AND now()>resolution_due_at AND status IN ('registered','in_analysis','in_treatment','reopened'); INSERT INTO public.sla_alerts(occurrence_id,alert_key) SELECT o.id,'res_'||threshold::text||'_c'||(o.reopen_count+1)::text FROM public.occurrences o JOIN public.accounts a ON a.id=o.account_id JOIN public.sla_targets t ON t.policy_id=a.sla_policy_id AND t.severity=o.severity CROSS JOIN unnest(ARRAY[50,80,100]) threshold WHERE o.status IN ('registered','in_analysis','in_treatment','reopened') AND public.business_minutes_between(a.calendar_id,o.resolution_started_at,now())-o.paused_business_minutes>=t.resolution_minutes*threshold/100 ON CONFLICT DO NOTHING; INSERT INTO public.sla_alerts(occurrence_id,alert_key) SELECT id,'update_'||extract(epoch FROM next_update_due_at)::bigint::text||'_c'||(reopen_count+1)::text FROM public.occurrences WHERE severity IN ('S1','S2') AND status IN ('registered','in_analysis','in_treatment','reopened') AND now()>next_update_due_at ON CONFLICT DO NOTHING; END $$;
COMMENT ON FUNCTION public.reopen_occurrence_from_customer(uuid,text) IS 'Server-only primitive. Public evaluation handler must validate and atomically consume a customer token before calling; no internal-role permission.';
COMMENT ON TABLE public.occurrence_sla_cycles IS 'Resolution timeline per cycle; snapshots retained across reopening for later KPI calculations.';